INSERT INTO clases (nombre, area, descripcion) VALUES ('Matemáticas', 'Ciencias Exactas', 'Razonamiento lógico, álgebra, cálculo y geometría.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Lengua Castellana', 'Humanidades y Letras', 'Comprensión lectora, producción textual y argumentación.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Ciencias Sociales', 'Ciencias Humanas', 'Historia de Colombia, geografía y competencias ciudadanas.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Ciencias Naturales y Biología', 'Ciencias Naturales', 'Ecología, sistemas biológicos y método científico.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Química', 'Ciencias Naturales', 'Estructura molecular, estequiometría y laboratorio escolar.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Física', 'Ciencias Exactas', 'Mecánica clásica, termodinámica y ondas.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Inglés', 'Lenguas Extranjeras', 'Gramática, fluidez verbal y listening según marco MCER.');
INSERT INTO clases (nombre, area, descripcion) VALUES ('Ética y Valores', 'Formación Integral', 'Resolución de conflictos, convivencia y empatía escolar.');
INSERT INTO rubricas (id, nombre, descripcion, escala_min, escala_max, tipo_escala) VALUES (1, 'Razonamiento y Pensamiento Matemático', 'Evaluación de habilidades lógicas, modelación y resolución de problemas.', 0.0, 5.0, 'CONTINUA'),(2, 'Habilidades de Comunicación y Lenguaje', 'Comprensión crítica, redacción coherente y argumentación oral.', 0.0, 5.0, 'CONTINUA'),(3, 'Indagación Científica y Pensamiento Crítico', 'Formulación de hipótesis, análisis de evidencias y rigor metodológico.', 0.0, 5.0, 'CONTINUA'),(4, 'Convivencia y Habilidades Socioemocionales', 'Trabajo en equipo, autorregulación y empatía.', 0.0, 5.0, 'CONTINUA');
INSERT INTO dimensiones_rubrica (rubrica_id, clave, nombre, peso_porcentual, descriptor_bajo, descriptor_basico, descriptor_alto, descriptor_superior) VALUES (1, 'dim_1_logica', 'Pensamiento Lógico y Estructurado', 35.0, 'Dificultades severas en secuencias deductivas.', 'Sigue secuencias simples con orientación.', 'Estructura argumentos lógicos sólidos.', 'Plantea deducciones abstractas impecables e innovadoras.'),(1, 'dim_2_resolucion', 'Resolución de Problemas y Modelación', 40.0, 'No logra formular un plan ante enunciados complejos.', 'Aplica algoritmos conocidos pero yerra en problemas abiertos.', 'Modela y resuelve problemas contextualizados con solvencia.', 'Propone múltiples estrategias de resolución y valida hipótesis.'),(1, 'dim_3_precision', 'Precisión y Comunicación Matemática', 25.0, 'Errores operativos constantes y notación confusa.', 'Notación adecuada pero explicaciones desordenadas.', 'Usa lenguaje matemático con claridad y orden.', 'Expresión simbólica y gráfica de nivel superior.'),(2, 'dim_1_comprension', 'Comprensión Lectora e Inferencia', 40.0, 'Lectura superficial sin captar ideas clave.', 'Identifica datos explícitos pero le cuesta inferir.', 'Infiere intenciones del autor y sintetiza argumentos.', 'Lectura crítica profunda relacionando intertextualidad.'),(2, 'dim_2_cohesion', 'Coherencia y Cohesión Escrita', 35.0, 'Párrafos inconexos y fallas ortográficas notorias.', 'Estructura oracional básica con conectores simples.', 'Párrafos fluidos, excelente vocabulario y correcta ortografía.', 'Estilo literario o ensayístico pulcro y elocuente.'),(2, 'dim_3_oralidad', 'Argumentación y Participación Verbal', 25.0, 'Inseguridad o apatía durante debates.', 'Expone puntos breves cuando se le pregunta directamente.', 'Participa con argumentos fundamentados y respeto.', 'Liderazgo discursivo y capacidad de réplica constructiva.'),(3, 'dim_1_hipotesis', 'Formulación de Hipótesis y Metodología', 50.0, 'No define variables ni formula hipótesis contrastables.', 'Formula preguntas guiadas y sigue instrucciones básicas.', 'Diseña planes de indagación y formula hipótesis válidas.', 'Pensamiento experimental riguroso y autónomo.'),(3, 'dim_2_evidencia', 'Análisis de Evidencias y Conclusiones', 50.0, 'Conclusiones no fundamentadas en los datos obtenidos.', 'Registra observaciones pero le cuesta relacionar variables.', 'Interpreta gráficos y extrae conclusiones coherentes.', 'Modela fenómenos empíricos y discute fuentes de error.'),(4, 'dim_1_equipo', 'Trabajo en Equipo y Escucha Activa', 35.0, 'Aislamiento o actitudes individualistas obstructivas.', 'Colabora de forma pasiva en el grupo.', 'Aporta activamente y escucha las ideas de otros.', 'Fomenta la sinergia grupal y motiva a sus compañeros.'),(4, 'dim_2_autorregulacion', 'Autorregulación y Manejo Emocional', 35.0, 'Reacciones explosivas o frustración desbordada.', 'Le cuesta mantener la calma bajo presión pero cede.', 'Maneja adecuadamente situaciones tensas o desacuerdos.', 'Madurez emocional sobresaliente y mediación asertiva.'),(4, 'dim_3_responsabilidad', 'Responsabilidad y Respeto Comunitario', 30.0, 'Incumplimiento de normas y faltas de respeto.', 'Cumple con deberes mínimos tras llamados de atención.', 'Respetuoso de acuerdos pedagógicos y puntual.', 'Ejemplo de civismo, ética y cuidado del entorno.');
