INSERT INTO modelos_informe (nombre, descripcion, tipo_informe, prompt_base) VALUES ('Informe de Rendimiento Trimestral para Padres', 'Informe pedagógico formativo y cercano, destacando fortalezas y plan de acción para el hogar.', 'INDIVIDUAL', 'Redactar un informe comprensivo y motivador dirigido a los padres de familia de [NOMBRE_ESTUDIANTE]. Describir su evolución en el trimestre, destacar sus logros principales y brindar recomendaciones prácticas para apoyar su proceso educativo en casa sin sobrecargarle.'),('Informe Diagnóstico de Clima de Aula y Convivencia', 'Evaluación grupal sobre trabajo en equipo, autorregulación y cohesión de aula.', 'AGREGADO', 'Analizar el desempeño y clima social del grupo. Señalar las materias con mayor solidez colectiva, los patrones de convivencia observados y estrategias recomendadas para el director de grupo.');